package com.bank.grpc;

import com.bank.grpc.gen.*;
import io.grpc.stub.StreamObserver;
import java.math.BigDecimal;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

// Server implementation generated base class: AccountServiceGrpc.AccountServiceImplBase
public class AccountServiceImpl extends AccountServiceGrpc.AccountServiceImplBase {
    private static final Logger log = Logger.getLogger(AccountServiceImpl.class.getName());
    private final Map<String, BigDecimal> balances = new ConcurrentHashMap<>(Map.of(
        "SAV2001", new BigDecimal("1000000"),   // Rajesh
        "CUR3001", new BigDecimal("250000")));   // Priya

    @Override
    public void transfer(TransferRequest req, StreamObserver<TransferResponse> obs) {
        BigDecimal amount = new BigDecimal(req.getAmount());
        log.info(() -> "gRPC Transfer Rs." + amount + " " + req.getFromAccount()
                + "->" + req.getToAccount());

        BigDecimal fromBal = balances.get(req.getFromAccount());
        if (fromBal == null || fromBal.compareTo(amount) < 0) {
            obs.onError(io.grpc.Status.FAILED_PRECONDITION
                .withDescription("insufficient funds").asRuntimeException());
            return;
        }
        balances.put(req.getFromAccount(), fromBal.subtract(amount));
        balances.merge(req.getToAccount(), amount, BigDecimal::add);

        TransferResponse resp = TransferResponse.newBuilder()
            .setTransferId("TXF-" + req.getIdempotencyKey())
            .setStatus("COMPLETED")
            .setFromBalance(balances.get(req.getFromAccount()).toString())
            .setToBalance(balances.get(req.getToAccount()).toString())
            .build();
        obs.onNext(resp);   // send the single response
        obs.onCompleted();  // close the call
    }
}
