package com.bank.grpc;

import com.bank.grpc.gen.*;
import io.grpc.ManagedChannel;
import io.grpc.ManagedChannelBuilder;
import java.util.UUID;
import java.util.logging.Logger;

public class TransferClient {
    private static final Logger log = Logger.getLogger(TransferClient.class.getName());

    public static void main(String[] args) {
        ManagedChannel channel = ManagedChannelBuilder
            .forAddress("localhost", 9090).usePlaintext().build();
        // Generated blocking stub → remote call feels like a local method.
        AccountServiceGrpc.AccountServiceBlockingStub stub =
            AccountServiceGrpc.newBlockingStub(channel);

        TransferResponse resp = stub.transfer(TransferRequest.newBuilder()
            .setFromAccount("SAV2001").setToAccount("CUR3001")
            .setAmount("50000").setIdempotencyKey(UUID.randomUUID().toString())
            .build());

        log.info(() -> "Status=" + resp.getStatus()
            + " Rajesh=Rs." + resp.getFromBalance()
            + " Priya=Rs." + resp.getToBalance());
        channel.shutdown();
    }
}
